// Lleva la salida de Gemini a `ia`. Descarta partes `thought`. Texto/JSON basura o error => {} (Apps Script responde "no entendi"). Sin bucles.
const j = $input.first().json || {};
let ia = {};
if (!j.error) {
  const partes = (j.content && j.content.parts) || j.parts || (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || [];
  let t = Array.isArray(partes) ? partes.filter((p) => p && !p.thought).map((p) => p.text || '').join('') : '';
  if (!t && typeof j.text === 'string') t = j.text;
  if (!t && typeof j.content === 'string') t = j.content;
  t = t.replace(/```json|```/g, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { const p = JSON.parse(t.slice(a, b + 1)); if (p && typeof p === 'object' && !Array.isArray(p)) ia = p; } catch (e) { /* basura => {} */ }
  }
}
return [{ json: { ia } }];

// Apps Script decide el negocio; este nodo solo adapta el contrato de transporte.
const norm = (s) => String(s ?? '').replace(/&(?!(amp|lt|gt|quot|#\d+);)/g, '&amp;').replace(/<(?!\/?(b|i|u|s|code|pre)>|a href="[^"]*">|\/a>)/g, '&lt;') || '(sin texto)';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r = $input.first().json || {};
const raw = $('Datos del mensaje').first().json.update || {};
const u = raw.update || raw;
const canal = u.canal || 'telegram';
const chatId = r.chatId ?? u.callback_query?.message?.chat?.id ?? u.message?.chat?.id;
if (!['telegram', 'whatsapp'].includes(canal)) throw new Error('Canal inválido');
const destino = canal === 'whatsapp' ? u.wa?.from : chatId;
if (destino === undefined || destino === null || destino === '') throw new Error('Destino ausente');
const botones = r.botones == null ? [] : r.botones;
if (!Array.isArray(botones) || botones.some(b => !b || !b.text || !b.callback_data || Buffer.byteLength(String(b.callback_data)) > 64)) throw new Error('Botones inválidos');
return [{ json: { canal, destino: String(destino), texto: r.tipo === 'aviso' ? esc(r.texto) : norm(r.texto), botones: botones.map(b => ({ text: String(b.text), callback_data: String(b.callback_data) })), editarMessageId: r.editarMensajeId == null ? '' : String(r.editarMensajeId), replyTo: r.replyTo ? String(canal === 'whatsapp' ? (u.wa?.wamid || '') : r.replyTo) : '', nombre: u.wa?.nombre || '', chatId, registroIds: Array.isArray(r.registroIds) ? r.registroIds : [], esEdicion: !!r.editarMensajeId }, pairedItem: { item: 0 } }];

// Prepara el update (caption => texto) y decide si hay archivo que descargar: voz/audio, foto (la mayor <= 1 MB; si ninguna, la menor) o documento imagen/PDF <= 10 MB.
const MAX = 10 * 1024 * 1024;
const FOTO_MAX = 1024 * 1024;
const raw = $input.first().json || {};
const upd = raw.update && typeof raw.update === 'object' ? raw.update : raw;
const m = upd.message;
let archivoInfo = null;
let update = upd;
let medio;
const tam = (f) => f.file_size || (f.width || 0) * (f.height || 0) || 0;
// T-049: el adaptador WA entrega un solo medio, sin tamaño ni resoluciones.
if (upd.canal === 'whatsapp') {
  if (m) {
    if (!m.text && m.caption) update = { ...upd, message: { ...m, text: m.caption } };
    const f = m.voice || (Array.isArray(m.photo) && m.photo[0]) || m.document;
    if (m.voice) medio = 'voz';
    if (f && f.file_id) {
      const id = f.file_unique_id || f.file_id;
      const mime = m.voice ? 'audio/ogg' : String(f.mime_type || '').split(';')[0].trim().toLowerCase();
      const ext = ({ 'audio/ogg': 'ogg', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'application/pdf': 'pdf' })[mime]
        || (mime.startsWith('image/') ? mime.slice(6).replace(/[^a-z0-9]/g, '').slice(0, 10) : 'bin');
      const nombre = m.voice ? 'nota_' + id + '.ogg' : m.photo ? 'foto_' + id + '.' + ext : (f.file_name || 'documento_' + id + '.' + ext);
      archivoInfo = { file_id: f.file_id, mime, nombre, file_unique_id: id, ...(m.voice ? { voz: true } : {}) };
    }
  }
  return [{ json: { update, archivoInfo, medio } }];
}
if (m) {
  if (!m.text && m.caption) update = { ...upd, message: { ...m, text: m.caption } };
  if (m.voice && m.voice.file_id) {
    medio = 'voz';
    if (!(m.voice.file_size > MAX)) archivoInfo = { file_id: m.voice.file_id, mime: 'audio/ogg', nombre: 'nota_' + m.voice.file_unique_id + '.ogg', file_unique_id: m.voice.file_unique_id, voz: true };
  } else if (m.audio && m.audio.file_id) {
    medio = 'voz';
    const am = String(m.audio.mime_type || '').toLowerCase();
    if (!(m.audio.file_size > MAX)) archivoInfo = { file_id: m.audio.file_id, mime: am.startsWith('audio/') ? am : 'audio/ogg', nombre: m.audio.file_name || ('audio_' + m.audio.file_unique_id), file_unique_id: m.audio.file_unique_id, voz: true };
  } else if (Array.isArray(m.photo) && m.photo.length) {
    const chicas = m.photo.filter((p) => !(p.file_size > FOTO_MAX));
    const f = chicas.length
      ? chicas.reduce((a, b) => (tam(b) >= tam(a) ? b : a))
      : m.photo.reduce((a, b) => (tam(b) <= tam(a) ? b : a));
    if (f.file_id && !(f.file_size > MAX)) archivoInfo = { file_id: f.file_id, mime: 'image/jpeg', nombre: 'foto_' + f.file_unique_id + '.jpg', file_unique_id: f.file_unique_id };
  } else if (m.document && m.document.file_id) {
    const dc = m.document, mime = String(dc.mime_type || '').toLowerCase();
    if ((mime.startsWith('image/') || mime === 'application/pdf') && !(dc.file_size > MAX)) {
      archivoInfo = { file_id: dc.file_id, mime, nombre: dc.file_name || ('documento_' + dc.file_unique_id), file_unique_id: dc.file_unique_id };
    }
  }
}
return [{ json: { update, archivoInfo, medio } }];

// Binario descargado => base64 para Apps Script (no para voz). `tipo` (voz|imagen|pdf|null) dice que IA puede usar el binario. Sin binario / muy grande / error => sin archivo.
const MAX = 10 * 1024 * 1024;
const info = $('Datos del mensaje').first().json.archivoInfo;
const it = $input.first();
// Un fallo WA debe pasar por autorización/deduplicación y cerrar sin registrar el caption.
const falloWA = () => {
  const upd = $('Datos del mensaje').first().json.update;
  if (upd.canal !== 'whatsapp') return [{ json: { archivo: null, tipo: null } }];
  const msg = { ...upd.message };
  for (const k of ['text', 'caption', 'voice', 'audio', 'photo', 'document', 'reply_to_message']) delete msg[k];
  msg.document = { mime_type: 'application/x-archivo-no-disponible' };
  return [{ json: { archivo: null, tipo: null, archivoErrorWA: true, updateSinArchivo: { ...upd, message: msg } } }];
};
if ($('Datos del mensaje').first().json.update.canal === 'whatsapp' && it.json?.error) return falloWA();
if (!info || !it.binary || !it.binary.data) return falloWA();
if (info.voz) return [{ json: { archivo: null, tipo: 'voz' } }];
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buf || !buf.length || buf.length > MAX) return falloWA();
const tipo = info.mime === 'application/pdf' ? 'pdf' : 'imagen';
return [{ json: { tipo, archivo: { base64: buf.toString('base64'), mime: info.mime, nombre: info.nombre, file_unique_id: info.file_unique_id } } }];

// Devuelve el binario descargado (voz/imagen/PDF) con su tipo MIME, para las IA con archivo. Sin binario => item vacio (la IA de texto no lo usa).
const esWA = $('Datos del mensaje').first().json.update.canal === 'whatsapp';
const descarga = esWA ? $('WA Binario archivo') : $('Descargar archivo');
if (!descarga.isExecuted) return [{ json: {} }];
// T-019: PDF con clave -> Apps Script devuelve `archivoIA` (copia sin clave); la IA lee esa. Sin archivoIA: el binario original, como siempre.
const ai = $('Procesar').first().json.archivoIA;
if (ai && ai.base64) return [{ json: {}, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(ai.base64, 'base64'), ai.nombre || 'archivo.pdf', 'application/pdf') } }];
const info = $('Datos del mensaje').first().json.archivoInfo;
const bin = descarga.first().binary;
if (!info || !bin || !bin.data) return [{ json: {} }];
const ext = esWA ? bin.data.fileExtension : (info.nombre.split('.').pop() || '').toLowerCase();
return [{ json: {}, binary: { data: { ...bin.data, fileName: info.nombre, fileExtension: ext, mimeType: info.mime } } }];

// Devuelve el binario descargado (voz/imagen/PDF) con su tipo MIME, para las IA con archivo. Sin binario => item vacio (la IA de texto no lo usa).
const esWA = $('Datos del mensaje').first().json.update.canal === 'whatsapp';
const descarga = esWA ? $('WA Binario archivo') : $('Descargar archivo');
if (!descarga.isExecuted) return [{ json: {} }];
const info = $('Datos del mensaje').first().json.archivoInfo;
const bin = descarga.first().binary;
if (!info || !bin || !bin.data) return [{ json: {} }];
const ext = esWA ? bin.data.fileExtension : (info.nombre.split('.').pop() || '').toLowerCase();
return [{ json: {}, binary: { data: { ...bin.data, fileName: info.nombre, fileExtension: ext, mimeType: info.mime } } }];

// Devuelve el binario descargado (voz/imagen/PDF) con su tipo MIME, para las IA con archivo. Sin binario => item vacio (la IA de texto no lo usa).
const esWA = $('Datos del mensaje').first().json.update.canal === 'whatsapp';
const descarga = esWA ? $('WA Binario archivo') : $('Descargar archivo');
if (!descarga.isExecuted) return [{ json: {} }];
const info = $('Datos del mensaje').first().json.archivoInfo;
const bin = descarga.first().binary;
if (!info || !bin || !bin.data) return [{ json: {} }];
const ext = esWA ? bin.data.fileExtension : (info.nombre.split('.').pop() || '').toLowerCase();
return [{ json: {}, binary: { data: { ...bin.data, fileName: info.nombre, fileExtension: ext, mimeType: info.mime } } }];

