const esWA = $('Datos del mensaje').first().json.update.canal === 'whatsapp';
const descarga = esWA ? $('WA Binario archivo') : $('Descargar archivo');
if (!descarga.isExecuted) return [{ json: {} }];
// T-019: PDF con clave -> Apps Script devuelve `archivoIA` (copia sin clave); la IA lee esa. Sin archivoIA: el binario original, como siempre.
const ai = $('Procesar').first().json.archivoIA;
if (ai && ai.base64) return [{ json: {}, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(ai.base64, 'base64'), ai.nombre || 'archivo.pdf', 'application/pdf') } }];
const info = $('Datos del mensaje').first().json.archivoInfo;
const bin = descarga.first().binary;
if (!info || !bin || !bin.data) return [{ json: {} }];
const ext = esWA ? bin.data.fileExtension : (info.nombre.split('.').pop() || '').toLowerCase();
return [{ json: {}, binary: { data: { ...bin.data, fileName: info.nombre, fileExtension: ext, mimeType: info.mime } } }];

// Un update por ejecución (Execute Workflow mode=each), directo o envuelto.
const raw = $input.first().json || {};
const u = JSON.parse(JSON.stringify(raw.update && typeof raw.update === 'object' ? raw.update : raw));
if (u.canal === 'whatsapp' && !u.wa?.context_id) {
  if (u.callback_query) return []; // Sin referencia no existe un botón verificable.
  if (u.message) delete u.message.reply_to_message;
}
return [{ json: u, pairedItem: { item: 0 } }];

const u = JSON.parse(JSON.stringify($('Preparar entrada').first().json));
const row = $input.first().json;
if (row.error) throw new Error('No se pudo leer contexto WA');
const digitos = v => String(v ?? '').replace(/\D/g, '');
let ctx = null;
try { ctx = JSON.parse(row.datos); } catch (_) { /* Sin contexto utilizable. */ }
const ts = Date.parse(ctx?.ts);
const valido = row.wamid === u.wa?.context_id && ctx && typeof ctx === 'object' && !Array.isArray(ctx)
  && !!digitos(ctx.destino) && digitos(ctx.destino) === digitos(u.wa?.from)
  && typeof ctx.tgMessageId === 'number' && Number.isSafeInteger(ctx.tgMessageId) && ctx.tgMessageId > 0
  && typeof ctx.texto === 'string' && ctx.texto.length <= 1000 && Array.isArray(ctx.botones)
  && Number.isFinite(ts) && ts >= Date.now() - 7 * 86400000 && ts <= Date.now() + 60000;
if (u.callback_query) {
  const data = u.callback_query.data;
  if (!valido || typeof data !== 'string' || !data || Buffer.byteLength(data) > 64 || !ctx.botones.includes(data)) return [];
  u.callback_query.message = { ...u.callback_query.message, message_id: ctx.tgMessageId, text: ctx.texto };
} else if (u.message) {
  if (valido) u.message.reply_to_message = { message_id: ctx.tgMessageId, text: ctx.texto };
  else delete u.message.reply_to_message;
}
return [{ json: u, pairedItem: { item: 0 } }];

const u = $('Restaurar contexto').first().json;
const r = $input.first().json;
if (r.error) throw new Error('No se pudo leer vigencia WA');
// Una edición en WA es un envío nuevo: el menú anterior queda sin efecto.
if (r.wamid !== u.wa.context_id) return [];
return [{ json: u, pairedItem: { item: 0 } }];

const u = $input.first().json;
const from = String(u.wa?.from || '').replace(/\D/g, '');
const context = u.wa?.context_id, data = u.callback_query?.data;
if (u.canal !== 'whatsapp' || !from || !context || typeof data !== 'string' || !data) throw new Error('Callback WA incompleto');
return [{ json: { update: u, clave: from + ':' + context + ':' + data, ejecucion: String($execution.id) }, pairedItem: { item: 0 } }];

const p = $('Preparar candado WA').first().json;
const rows = $input.all().map(i => i.json);
if (rows.some(r => r.error || !Number.isSafeInteger(Number(r.id)) || Number(r.id) <= 0 || r.clave !== p.clave || typeof r.ejecucion !== 'string' || !r.ejecucion)) throw new Error('No se pudo verificar candado WA');
const primero = rows.sort((a, b) => Number(a.id) - Number(b.id))[0];
if (!primero) throw new Error('Candado WA sin reserva');
if (primero.ejecucion !== String($execution.id)) return [];
return [{ json: p.update, pairedItem: { item: 0 } }];

// La URL solo procede de Graph autenticado. No aceptar URL del mensaje ni redirecciones.
const meta = $input.first().json || {};
const info = $('Datos del mensaje').first().json.archivoInfo;
const url = String(meta.url || '');
if (!/^https:\/\/lookaside\.fbsbx\.com\//i.test(url) || /[\\\s\u0000-\u001f\u007f]/.test(url)) throw new Error('URL de archivo WhatsApp no permitida');
const size = meta.file_size;
if (typeof size !== 'number' || !Number.isSafeInteger(size) || size <= 0 || size > 10 * 1024 * 1024) throw new Error('Tamaño de archivo WhatsApp inválido: máximo 10 MB');
const mime = String(meta.mime_type || '').split(';')[0].trim().toLowerCase();
const datos = $('Datos del mensaje').first().json;
const esFoto = Array.isArray(datos.update.message?.photo);
const permitido = info && (info.voz ? mime === 'audio/ogg' : esFoto ? ['image/jpeg', 'image/png', 'image/webp'].includes(mime) : mime === 'application/pdf' || /^image\/[a-z0-9][a-z0-9.+-]*$/.test(mime));
if (!permitido || mime !== info.mime) throw new Error('MIME de archivo WhatsApp incoherente');
return [{ json: { url, mime_type: mime, file_size: size } }];

// Misma propiedad binaria que getFile de Telegram; no confiar en nombre/MIME del HTTP.
const item = $input.first();
const info = $('Datos del mensaje').first().json.archivoInfo;
if (!info || !item.binary?.data) throw new Error('Archivo WhatsApp sin binario');
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buf || !buf.length || buf.length > 10 * 1024 * 1024) throw new Error('Archivo WhatsApp vacío o mayor de 10 MB');
const ext = ({ 'audio/ogg': 'ogg', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'application/pdf': 'pdf' })[info.mime]
  || info.mime.slice(6).replace(/[^a-z0-9]/g, '').slice(0, 10);
return [{ json: {}, binary: { data: { ...item.binary.data, mimeType: info.mime, fileName: info.nombre, fileExtension: ext } } }];

// Apps Script conserva permisos y update_id; solo sustituir el aviso de archivo no legible.
const r = $input.first().json;
const fallo = $('Armar archivo').isExecuted && $('Armar archivo').first().json.archivoErrorWA;
if (!fallo || r.tipo !== 'responder') return [{ json: r }];
return [{ json: { ...r, texto: 'No pude leer el archivo de WhatsApp. Reenvíe una foto JPG, PNG o WebP, un PDF o una nota de voz OGG de máximo 10 MB, o escriba el contenido.' } }];
